    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello प्रदीप आपकी one inch brass premium duck hinge की request IndiaMART पर raise है।"
    },
    {
      "i": 1,
      "speaker": "bot",
      "text": "बस उसी के लिए कुछ details confirm करनी थी।"
    },
    {
      "i": 2,
      "speaker": "caller",
      "text": "नहीं Eid तो आपने वो करवा लिया था बात करवाई नहीं है आपने अभी तक।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "क्षमा कीजिएगा मैं अभी आपकी पूरी मदद करता हूं।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "बस कुछ details confirm कर लेते हैं ताकि सही seller से आपकी बात..."
    },
    {
      "i": 5,
      "speaker": "caller",
      "text": "ठीक है।"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "ये तो बता दीजिए मैंने आपसे detail तो बता दीजिए।"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "मैं समझ सकता हूं but बस एक छोटी सी जानकारी और चाहिए थी।"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "आपको finish type में steel चाहिए silver या कुछ?"
    },
    {
      "i": 9,
      "speaker": "caller",
      "text": "finishing में steel चीज है silver silver सबसे कम मतलब वो चीज है हमारे पास।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "ठीक है जानकारी के लिए शुक्रिया।"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "क्या आप इस product के बारे में कोई और details या specification share करना चाहेंगे?"
    },
    {
      "i": 12,
      "speaker": "caller",
      "text": "detail जानी तभी तो कह रहा मैं मैंने न्यू पूछना भई यो उन्नी एम एम में आवे और और half में भी आवे ये क्या category में आवे।"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "मैं समझ सकता हूँ।"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "आपकी details note कर ली गई हैं और जल्द ही एक seller आपसे contact करेंगे IndiaMART के जरिए।"
    },
    {
      "i": 15,
      "speaker": "caller",
      "text": "वगैरह का।"
    },
    {
      "i": 16,
      "speaker": "caller",
      "text": "Hello."
    }
  ]
